```typescript
function removeDuplicados(valores: string[]): string[] {
    const result: string[] = [];
    for (const valor of valores) {
        if (result.length === 0 || valor !== result[result.length - 1]) {
            result.push(valor);
        }
    }
    return result;
}

console.assert(JSON.stringify(removeDuplicados(['ana', 'bia', 'ana', 'caio', 'bia'])) === JSON.stringify(['ana', 'bia', 'caio']));
console.assert(JSON.stringify(removeDuplicados([])) === JSON.stringify([]));
console.assert(JSON.stringify(removeDuplicados(['x'])) === JSON.stringify(['x']));
